pub fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    assert!(tol > 0, "tolerance must be strictly positive");

    // Compute in wider type to avoid i8 overflow (e.g., -128 - 127).
    let diff: i16 = a as i16 - b as i16;
    let t: i16 = tol as i16;

    (-t < diff) && (diff < t)
}

pub fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    assert!(!a.is_empty(), "input length must be > 0");
    assert_eq!(a.len(), b.len(), "inputs must have equal length");
    assert!(tol > 0, "tolerance must be strictly positive");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}